```javascript
/**
 * retry(operation, options)
 * @param {Function} operation - async ({attempt, signal}) => any
 * @param {Object} options
 * @param {number} options.attempts - 总尝试次数，必须为正安全整数
 * @param {number} options.baseDelayMs - 基础延迟毫秒数，必须为非负安全整数
 * @param {Function} [options.sleep] - (ms, signal) => Promise<void>，可注入
 * @param {AbortSignal} [options.signal] - AbortSignal
 */
async function retry(operation, options = {}) {
  const { attempts, baseDelayMs, sleep, signal } = options;

  // --- 1. 参数校验 ---
  if (!Number.isSafeInteger(attempts) || attempts <= 0) {
    throw new TypeError('attempts must be a positive safe integer');
  }
  if (!Number.isSafeInteger(baseDelayMs) || baseDelayMs < 0) {
    throw new TypeError('baseDelayMs must be a non-negative safe integer');
  }

  // 默认 sleep 实现：使用 setTimeout + signal 监听
  const defaultSleep = (ms, sig) => new Promise((resolve, reject) => {
    if (sig?.aborted) {
      return reject(sig.reason ?? new Error('ABORTED'));
    }
    const timer = setTimeout(() => {
      cleanup();
      resolve();
    }, ms);
    const onAbort = () => {
      clearTimeout(timer);
      cleanup();
      reject(sig.reason ?? new Error('ABORTED'));
    };
    const cleanup = () => {
      if (sig) sig.removeEventListener('abort', onAbort);
    };
    if (sig) sig.addEventListener('abort', onAbort, { once: true });
  });

  const doSleep = typeof sleep === 'function' ? sleep : defaultSleep;

  // --- 2. 辅助函数 ---
  const isAbortError = (err) => {
    return err?.name === 'AbortError' || 
           (signal && err === signal.reason) ||
           (signal?.aborted && err === signal.reason);
  };

  const getAbortReason = () => {
    if (signal?.aborted) {
      return signal.reason ?? new Error('ABORTED');
    }
    return null;
  };

  // --- 3. 主循环 ---
  let lastError;

  for (let attempt = 1; attempt <= attempts; attempt++) {
    // 每次尝试前检查是否已取消
    const abortReason = getAbortReason();
    if (abortReason) {
      throw abortReason;
    }

    try {
      // 执行 operation
      const result = await operation({ attempt, signal });
      return result;
    } catch (err) {
      lastError = err;

      // 如果是取消错误，立即抛出，不重试
      if (isAbortError(err)) {
        throw err;
      }

      // 如果已经是最后一次尝试，直接抛出错误
      if (attempt === attempts) {
        throw lastError;
      }

      // 计算延迟时间: baseDelayMs * 2^(attempt-1)
      const delay = baseDelayMs * Math.pow(2, attempt - 1);

      // 指数溢出检查：必须在调用 sleep 前拒绝
      if (!Number.isSafeInteger(delay) || delay > Number.MAX_SAFE_INTEGER) {
        throw new Error('INVALID_DELAY');
      }

      // 等待延迟（期间可能取消）
      try {
        await doSleep(delay, signal);
      } catch (sleepErr) {
        // sleep 抛错也按相同规则处理
        if (isAbortError(sleepErr)) {
          throw sleepErr;
        }
        // 非取消的 sleep 错误视为失败，继续下一轮或最终抛出
        lastError = sleepErr;
        if (attempt === attempts) {
          throw lastError;
        }
        continue;
      }
    }
  }

  // 理论上不会到达这里，因为循环内要么返回要么抛出
  throw lastError;
}
```

### 边界说明

| 场景 | 行为 |
|------|------|
| `attempts` 非正安全整数 | 抛出 `TypeError` |
| `baseDelayMs` 为负或非安全整数 | 抛出 `TypeError` |
| `signal` 在首次尝试前已取消 | 立即以 `signal.reason`（缺省 `Error('ABORTED')`）失败，不执行任何 `operation` |
| `signal` 在 `operation` 执行期间取消 | `operation` 内部应自行响应；若 `operation` 未响应而正常完成，则返回结果；若 `operation` 因取消而抛出 `AbortError`，立即失败不重试 |
| `signal` 在 `sleep` 期间取消 | `sleep` 被中断并抛出取消原因，立即失败不重试 |
| `operation` 同步抛错 | 被 `try/catch` 捕获，按异步错误同等处理：取消类错误不重试，其他错误进入延迟重试流程 |
| `sleep` 同步抛错 | 同上，取消类不重试，其他错误记录后继续或最终抛出 |
| 指数溢出 | `baseDelayMs * 2^(attempt-1)` 超出安全整数范围时，在调用 `sleep` **之前**抛出 `Error('INVALID_DELAY')` |
| 最后一次尝试失败 | 不执行 `sleep`，直接抛出最后一次的错误 |
| `baseDelayMs = 0` | 延迟始终为 0，但仍会调用 `sleep(0, signal)`（除非是最后一次尝试） |
| 自定义 `sleep` 未提供 | 使用内置默认 `sleep`，基于 `setTimeout` + `AbortSignal` |

### 定向测试

