// ===== 测试工具 =====
const assert = require('assert');

function createAbortController() {
  return new AbortController();
}

// ===== Test 1: 成功路径 =====
(async () => {
  let callCount = 0;
  const op = async ({ attempt }) => {
    callCount++;
    if (attempt < 3) throw new Error(`fail-${attempt}`);
    return 'success';
  };
  const result = await retry(op, { attempts: 5, baseDelayMs: 1 });
  assert.strictEqual(result, 'success');
  assert.strictEqual(callCount, 3);
  console.log('Test 1 passed: success after retries');
})();

// ===== Test 2: 全部失败，抛出最后一次错误 =====
(async () => {
  const errors = [];
  const op = async ({ attempt }) => {
    const e = new Error(`err-${attempt}`);
    errors.push(e);
    throw e;
  };
  try {
    await retry(op, { attempts: 3, baseDelayMs: 1 });
    assert.fail('should have thrown');
  } catch (e) {
    assert.strictEqual(e.message, 'err-3');
    assert.strictEqual(errors.length, 3);
  }
  console.log('Test 2 passed: all attempts fail, throws last error');
})();

// ===== Test 3: signal 预先取消，不执行 operation =====
(async () => {
  const ac = createAbortController();
  ac.abort(new Error('pre-abort'));
  let called = false;
  const op = async () => { called = true; return 'x'; };
  try {
    await retry(op, { attempts: 3, baseDelayMs: 1, signal: ac.signal });
    assert.fail('should have thrown');
  } catch (e) {
    assert.strictEqual(e.message, 'pre-abort');
    assert.strictEqual(called, false);
  }
  console.log('Test 3 passed: pre-cancelled signal skips operation');
})();

// ===== Test 4: signal 在 sleep 期间取消 =====
(async () => {
  const ac = createAbortController();
  let attemptNum = 0;
  const op = async ({ attempt }) => {
    attemptNum = attempt;
    throw new Error('op-fail');
  };
  const customSleep = (ms, sig) => new Promise((_, reject) => {
    setTimeout(() => ac.abort(new Error('mid-sleep-abort')), 5);
    sig.addEventListener('abort', () => reject(ac.signal.reason), { once: true });
  });
  try {
    await retry(op, { attempts: 5, baseDelayMs: 100, sleep: customSleep, signal: ac.signal });
    assert.fail('should have thrown');
  } catch (e) {
    assert.strictEqual(e.message, 'mid-sleep-abort');
    assert.strictEqual(attemptNum, 1); // 只执行了第一次
  }
  console.log('Test 4 passed: cancel during sleep stops retry');
})();

// ===== Test 5: AbortError 永不重试 =====
(async () => {
  let count = 0;
  const op = async () => {
    count++;
    const err = new Error('aborted');
    err.name = 'AbortError';
    throw err;
  };
  try {
    await retry(op, { attempts: 5, baseDelayMs: 1 });
    assert.fail('should have thrown');
  } catch (e) {
    assert.strictEqual(e.name, 'AbortError');
    assert.strictEqual(count, 1); // 不重试
  }
  console.log('Test 5 passed: AbortError never retried');
})();

// ===== Test 6: 指数溢出检测（隔离 sleep 副作用）=====
(async () => {
  const recordedDelays = [];
  let operationCalls = 0;

  const op = async ({ attempt }) => {
    operationCalls++;
    throw new Error('always-fail');
  };

  // Mock sleep: 记录接收到的 ms，但不实际等待，立即 resolve
  const mockSleep = async (ms, sig) => {
    recordedDelays.push(ms);
    // 验证传入 sleep 的值必须是安全整数
    assert.ok(Number.isSafeInteger(ms), `sleep received unsafe integer: ${ms}`);
  };

  try {
    // baseDelayMs=1, attempts=64
    // attempt=1 -> delay=1*2^0=1 (safe) -> sleep(1)
    // ...
    // attempt=53 -> delay=1*2^52 (safe, MAX_SAFE_INT=2^53-1) -> sleep(2^52)
    // attempt=54 -> delay=1*2^53 (unsafe) -> throw INVALID_DELAY BEFORE sleep
    await retry(op, { attempts: 64, baseDelayMs: 1, sleep: mockSleep });
    assert.fail('should have thrown INVALID_DELAY');
  } catch (e) {
    assert.strictEqual(e.message, 'INVALID_DELAY');

    // 断言：sleep 只被调用了 53 次（attempt 1 到 53 失败后各一次）
    // attempt 54 计算出溢出，在调用 sleep 前抛出，所以 sleep 没有被第 54 次调用
    assert.strictEqual(recordedDelays.length, 53, `Expected 53 sleep calls, got ${recordedDelays.length}`);

    // 断言：所有记录的 delay 都是安全整数
    recordedDelays.forEach(d => {
      assert.ok(Number.isSafeInteger(d));
    });

    // 断言：operation 被调用了 54 次（第 54 次失败后计算 delay 溢出）
    assert.strictEqual(operationCalls, 54);
  }
  console.log('Test 6 passed: exponential overflow detected before sleep call, sleep isolated');
})();

// ===== Test 7: 参数校验 =====
(async () => {
  const op = async () => 'ok';
  await assert.rejects(
    () => retry(op, { attempts: 0, baseDelayMs: 1 }),
    /positive safe integer/
  );
  await assert.rejects(
    () => retry(op, { attempts: 1.5, baseDelayMs: 1 }),
    /positive safe integer/
  );
  await assert.rejects(
    () => retry(op, { attempts: 3, baseDelayMs: -1 }),
    /non-negative safe integer/
  );
  console.log('Test 7 passed: invalid parameters rejected');
})();

// ===== Test 8: 最后一次失败不 sleep =====
(async () => {
  let sleepCalls = 0;
  const op = async () => { throw new Error('fail'); };
  const spySleep = async (ms, sig) => { sleepCalls++; };
  try {
    await retry(op, { attempts: 3, baseDelayMs: 10, sleep: spySleep });
  } catch (e) { /* expected */ }
  assert.strictEqual(sleepCalls, 2); // 第1、2次失败后各sleep一次，第3次不sleep
  console.log('Test 8 passed: no sleep after last attempt');
})();

// ===== Test 9: operation 同步抛错按相同规则处理 =====
(async () => {
  let count = 0;
  const op = ({ attempt }) => {
    count++;
    if (attempt < 2) throw new Error('sync-fail');
    return 'ok';
  };
  const result = await retry(op, { attempts: 3, baseDelayMs: 1 });
  assert.strictEqual(result, 'ok');
  assert.strictEqual(count, 2);
  console.log('Test 9 passed: sync throw handled like async rejection');
})();

// ===== Test 10: baseDelayMs=0 仍调用 sleep =====
(async () => {
  let sleepArgs = [];
  const op = async ({ attempt }) => {
    if (attempt < 2) throw new Error('f');
    return 'done';
  };
  const spySleep = async (ms, sig) => { sleepArgs.push(ms); };
  const result = await retry(op, { attempts: 3, baseDelayMs: 0, sleep: spySleep });
  assert.strictEqual(result, 'done');
  assert.deepStrictEqual(sleepArgs, [0]); // 第一次失败后 sleep(0)，第二次成功不再 sleep
  console.log('Test 10 passed: baseDelayMs=0 still calls sleep with 0');
})();
